<?php
declare(strict_types=1);
require_once __DIR__.'/../modules/auth.php';require_once __DIR__.'/../modules/affiliate-community.php';require_login();start_app_session();if(empty($_SESSION['support_csrf']))$_SESSION['support_csrf']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['support_csrf'];$error='';$flash='';$threadId=trim((string)($_GET['thread']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Atualize a página.');}$threadId=trim((string)($_POST['thread_id']??''));try{$action=(string)($_POST['action']??'reply');if($action==='close'){if(!app_user_can('support','close'))throw new DomainException('Sem permissão para encerrar conversas.');affiliate_support_close($threadId);$flash='Conversa encerrada.';}else{if(!app_user_can('support','reply'))throw new DomainException('Sem permissão para responder.');affiliate_support_reply($threadId,(string)($_POST['body']??''),'producer');$flash='Resposta enviada.';}}catch(DomainException $e){$error=$e->getMessage();}catch(Throwable $e){$error='Não foi possível atualizar a conversa.';error_log('[AFFILIEY] support: '.$e->getMessage());}}
$q=app_db()->prepare('SELECT th.*,a.name AS affiliate_name,a.email FROM affiliate_support_threads th JOIN affiliates a ON a.tenant_id=th.tenant_id AND a.id=th.affiliate_id WHERE th.tenant_id=? ORDER BY th.updated_at DESC');$q->execute([tenant_id()]);$threads=$q->fetchAll();$selected=null;foreach($threads as $th)if($th['id']===$threadId)$selected=$th;$messages=$selected?affiliate_support_messages($threadId,false):[];function su_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suporte — AFFILIEY</title><link rel="stylesheet" href="/assets/css/app-theme.css?v=3"><link rel="stylesheet" href="/assets/css/brand.css?v=affiliey4"><link rel="stylesheet" href="/assets/css/profile-environments.css?v=1"><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/brand/affiliey-favicon.png"></head><body class="app-shell"><header class="topbar"><a class="brand" href="dashboard.php"><img class="brand-logo" src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"></a><nav class="main-nav"><?= app_workspace_navigation() ?></nav><div class="top-actions"><?= app_header_account_tools() ?><span><?= su_e(current_user()['name']??'') ?></span><a href="login.php?logout=1">Sair</a></div></header><main class="profile-page"><div class="profile-heading"><div><span class="profile-eyebrow">RELACIONAMENTO COM AFILIADOS</span><h1>Caixa de suporte</h1><p>Conversas privadas vinculadas a afiliados ativos deste espaço.</p></div></div><?php if($error): ?><p class="message error" role="alert"><?= su_e($error) ?></p><?php endif; ?><?php if($flash): ?><p class="message success" role="status"><?= su_e($flash) ?></p><?php endif; ?><div class="support-layout"><section class="profile-panel"><div class="profile-panel-head"><div><h2>Conversas</h2><p><?= count($threads) ?> atendimento(s)</p></div></div><?php if(!$threads): ?><p class="profile-muted">Nenhuma solicitação recebida.</p><?php else: ?><div class="support-thread-list"><?php foreach($threads as $th): ?><a href="support.php?thread=<?= rawurlencode($th['id']) ?>" class="<?= $th['id']===$threadId?'selected':'' ?>"><b><?= su_e($th['subject']) ?></b><span><?= su_e($th['affiliate_name']) ?> · <?= su_e($th['status']==='open'?'Aberta':'Encerrada') ?></span><small><?= su_e(date('d/m H:i',strtotime($th['updated_at']))) ?></small></a><?php endforeach; ?></div><?php endif; ?></section><section class="profile-panel"><?php if(!$selected): ?><p class="profile-muted">Selecione uma conversa para ler e responder.</p><?php else: ?><div class="profile-panel-head"><div><h2><?= su_e($selected['subject']) ?></h2><p><?= su_e($selected['affiliate_name']) ?> · <?= su_e($selected['email']) ?></p></div><span class="profile-status"><?= su_e($selected['status']) ?></span></div><div class="support-messages"><?php foreach($messages as $message): ?><article class="<?= $message['sender_profile']==='producer'?'from-producer':'from-affiliate' ?>"><b><?= su_e($message['sender_name']) ?></b><p><?= nl2br(su_e($message['body'])) ?></p><small><?= su_e(date('d/m/Y H:i',strtotime($message['created_at']))) ?></small></article><?php endforeach; ?></div><?php if($selected['status']==='open'&&app_user_can('support','reply')): ?><form method="post" class="community-form support-reply"><input type="hidden" name="csrf" value="<?= su_e($csrf) ?>"><input type="hidden" name="thread_id" value="<?= su_e($selected['id']) ?>"><input type="hidden" name="action" value="reply"><label>Resposta<textarea name="body" maxlength="5000" rows="4" required></textarea></label><button class="button primary" type="submit">Enviar resposta</button></form><?php endif; ?><?php if($selected['status']==='open'&&app_user_can('support','close')): ?><form method="post" class="support-close"><input type="hidden" name="csrf" value="<?= su_e($csrf) ?>"><input type="hidden" name="thread_id" value="<?= su_e($selected['id']) ?>"><input type="hidden" name="action" value="close"><button class="button" type="submit">Encerrar atendimento</button></form><?php endif; ?><?php endif; ?></section></div></main></body></html>
